function retrieveTokensForWithdraw(RetrieveData[] calldata retrieveData) public onlyManager nonReentrant {
    uint256 amountAskedForWithdraw_temp = 0;
    uint256 neededAssets = neededAssetsForWithdraw();
    for (uint256 i = 0; i < retrieveData.length; i++) {
        if (!registry.isAnActiveConnector(vaultId, retrieveData[i].connectorAddress)) {
            continue;
        }
        uint256 balanceBefore = baseToken.balanceOf(address(this));
        uint256 amount = IConnector(retrieveData[i].connectorAddress).sendTokensToTrustedAddress(
            address(baseToken), retrieveData[i].withdrawAmount, address(this), retrieveData[i].data
        );
        uint256 balanceAfter = baseToken.balanceOf(address(this));
        if (balanceBefore + amount > balanceAfter) revert NoyaAccounting_banalceAfterIsNotEnough();
        amountAskedForWithdraw_temp += retrieveData[i].withdrawAmount;
        emit RetrieveTokensForWithdraw(
            retrieveData[i].withdrawAmount,
            retrieveData[i].connectorAddress,
            amount,
            amountAskedForWithdraw + amountAskedForWithdraw_temp
        );
    }
    amountAskedForWithdraw += amountAskedForWithdraw_temp;
    if (amountAskedForWithdraw_temp > neededAssets) {
        revert NoyaAccounting_INVALID_AMOUNT();
    }
}

function sendTokensToTrustedAddress(address token, uint256 amount, address caller, bytes memory data)
    external
    returns (uint256)
{
    emit TransferTokensToTrustedAddress(token, amount, caller, data);
    (address accountingManager,) = registry.getVaultAddresses(vaultId);
    if (msg.sender == accountingManager) {
        (,,,, address watcherContract,) = registry.getGovernanceAddresses(vaultId);

        (uint256 newAmount, bytes memory newData) = abi.decode(data, (uint256, bytes));
        Watchers(watcherContract).verifyRemoveLiquidity(amount, newAmount, newData);

        IERC20(token).safeTransfer(address(accountingManager), newAmount);
        amount = newAmount;
    } else if (registry.isAnActiveConnector(vaultId, msg.sender) || msg.sender == registry.flashLoan()) {
        IERC20(token).safeTransfer(address(msg.sender), amount);
    } else {
        uint256 routeId = abi.decode(data, (uint256));
        swapHandler.verifyRoute(routeId, msg.sender);
        if (caller != address(this)) revert IConnector_InvalidAddress(caller);
        IERC20(token).safeTransfer(msg.sender, amount);
    }
    _updateTokenInRegistry(token);
    return amount;
}

function fulfillCurrentWithdrawGroup() public onlyManager nonReentrant whenNotPaused {
    require(currentWithdrawGroup.isStarted == true && currentWithdrawGroup.isFullfilled == false);
    uint256 neededAssets = neededAssetsForWithdraw();

    if (neededAssets != 0 && amountAskedForWithdraw != currentWithdrawGroup.totalCBAmount) {
        revert NoyaAccounting_NOT_READY_TO_FULFILL();
    }
    currentWithdrawGroup.isFullfilled = true;
    amountAskedForWithdraw = 0;
    uint256 availableAssets = baseToken.balanceOf(address(this)) - depositQueue.totalAWFDeposit;
    if (availableAssets >= currentWithdrawGroup.totalCBAmount) {
        currentWithdrawGroup.totalABAmount = currentWithdrawGroup.totalCBAmount;
    } else {
        currentWithdrawGroup.totalABAmount = availableAssets;
    }
    currentWithdrawGroup.totalCBAmountFullfilled = currentWithdrawGroup.totalCBAmount;
    currentWithdrawGroup.totalCBAmount = 0;
    emit WithdrawGroupFulfilled(
        currentWithdrawGroup.lastId, currentWithdrawGroup.totalCBAmount, currentWithdrawGroup.totalABAmount
    );
}

function supply(address market, address asset, uint256 amount) external onlyManager nonReentrant {
    _approveOperations(asset, market, amount);
    if (!registry.isTokenTrusted(vaultId, asset, address(this))) revert IConnector_UntrustedToken(asset);
    IComet(market).supply(asset, amount);
    registry.updateHoldingPosition(
        vaultId, registry.calculatePositionId(address(this), COMPOUND_LP, abi.encode(market)), "", "", false
    );
    _updateTokenInRegistry(asset);
    emit Supply(market, asset, amount);
}

function getBorrowBalanceInBase(IComet comet) public view returns (uint256 borrowBalanceInVirtualBase) {
    uint256 borrowBalanceInBase = comet.borrowBalanceOf(address(this));
    if (borrowBalanceInBase == 0) return 0;
    address basePriceFeed = comet.baseTokenPriceFeed();
    uint256 basePriceInVirtualBase = comet.getPrice(basePriceFeed);
    borrowBalanceInVirtualBase = (borrowBalanceInBase * basePriceInVirtualBase) / comet.baseScale();
}

function getAccountHealthFactor(IComet comet) public view returns (uint256) {
    // Get the amount of base debt owed adjusted for price.
    uint256 borrowBalanceInBase = getBorrowBalanceInBase(comet);
    if (borrowBalanceInBase == 0) return type(uint256).max;
    return getCollBlanace(comet, true) * 1e18 / borrowBalanceInBase;
}

